(function(){
  function drawBar(ctx,w,h,labels,vals){ctx.clearRect(0,0,w,h);ctx.fillStyle='#64748b';ctx.font='12px sans-serif';var max=Math.max(1,...vals);var pad=28;var bw=Math.max(18,(w-pad*2)/(vals.length||1)-12);vals.forEach(function(v,i){var x=pad+i*(bw+12), bh=(h-60)*(v/max);ctx.fillStyle='#0284c7';ctx.fillRect(x,h-34-bh,bw,bh);ctx.fillStyle='#334155';ctx.fillText(String(labels[i]||''),x,h-12);});}
  function drawLine(ctx,w,h,labels,vals){ctx.clearRect(0,0,w,h);var max=Math.max(1,...vals), pad=28;ctx.strokeStyle='#0284c7';ctx.lineWidth=2;ctx.beginPath();vals.forEach(function(v,i){var x=pad+(w-pad*2)*(i/Math.max(1,vals.length-1));var y=h-34-(h-70)*(v/max);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();ctx.fillStyle='#334155';ctx.font='12px sans-serif';labels.forEach(function(l,i){if(i%Math.ceil(labels.length/5||1)===0)ctx.fillText(String(l),pad+(w-pad*2)*(i/Math.max(1,labels.length-1)),h-12);});}
  function drawDoughnut(ctx,w,h,labels,vals){ctx.clearRect(0,0,w,h);var total=vals.reduce((a,b)=>a+b,0)||1;var colors=['#dc2626','#d97706','#0284c7','#16a34a','#64748b'];var start=-Math.PI/2,cx=w/2,cy=h/2-10,r=Math.min(w,h)/3;vals.forEach(function(v,i){var end=start+(v/total)*Math.PI*2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.fillStyle=colors[i%colors.length];ctx.arc(cx,cy,r,start,end);ctx.closePath();ctx.fill();start=end;});ctx.globalCompositeOperation='destination-out';ctx.beginPath();ctx.arc(cx,cy,r*.62,0,Math.PI*2);ctx.fill();ctx.globalCompositeOperation='source-over';ctx.fillStyle='#334155';ctx.font='12px sans-serif';labels.forEach(function(l,i){ctx.fillText(String(l),12,18+i*16);});}
  window.Chart=function(canvas,config){var ctx=canvas.getContext('2d');var box=canvas.parentElement;canvas.width=box.clientWidth||500;canvas.height=box.clientHeight||260;var labels=(config.data&&config.data.labels)||[];var vals=((config.data&&config.data.datasets&&config.data.datasets[0]&&config.data.datasets[0].data)||[]).map(Number);if(config.type==='line')drawLine(ctx,canvas.width,canvas.height,labels,vals);else if(config.type==='doughnut')drawDoughnut(ctx,canvas.width,canvas.height,labels,vals);else drawBar(ctx,canvas.width,canvas.height,labels,vals);};
  window.Chart.defaults={font:{},color:'#64748b'};
})();
